# 0.3.6: 0.3.4's migPlan with its table as arguments (the run-once id + marker, the key, old / new text, append a missing line?, the kept
# note's tail); 0.3.4's add rule only when addMissing (rebirth.max: a missing line already reads the new default - marker only)
M(cfg, r"""
public static Object[] migPlanT(String text, String id, String mark, String key, String oldV, String newV, boolean addMissing, String keptTail) {
  if (text == null) return null;
  java.util.Properties p = new java.util.Properties();
  try { p.load(new java.io.StringReader(text)); } catch (Throwable t) { return null; }
  String[] raw = text.split("\n", -1);
  java.util.ArrayList l = new java.util.ArrayList();
  for (int i = 0; i < raw.length; i++) {
    String s0 = raw[i];
    if (s0.endsWith("\r")) s0 = s0.substring(0, s0.length() - 1);
    l.add(s0);
  }
  String eff = null;
  boolean multi = false;
  int lastEnd = -1;
  int k = 0;
  while (k < l.size()) {
    String s = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s)) {
      if (s.indexOf(id) >= 0) return null;
      k++;
      continue;
    }
    int e = @PKG@.CfgFile.end(l, k);
    if (key.equals(@PKG@.CfgFile.key(s))) { eff = @PKG@.CfgFile.value(l, k).trim(); multi = e > k; lastEnd = e; }
    k = e + 1;
  }
  boolean add = addMissing && eff == null;
  boolean mig = add || (eff != null && !multi && eff.equals(oldV));
  String kept = (!mig && eff != null) ? key + "=" + @PKG@.CfgRows.oneLine(p.getProperty(key)) + keptTail : "";
  String cr = text.indexOf("\r\n") >= 0 ? "\r" : "";
  java.util.ArrayList out = new java.util.ArrayList();
  boolean placed = false;
  k = 0;
  while (k < l.size()) {
    String s2 = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s2)) { out.add(raw[k]); k++; continue; }
    int e2 = @PKG@.CfgFile.end(l, k);
    if (mig && !add && key.equals(@PKG@.CfgFile.key(s2)) && e2 == k && @PKG@.CfgFile.value(l, k).trim().equals(oldV)) {
      out.add(s2.substring(0, @PKG@.CfgFile.valStart(s2)) + newV + (raw[k].endsWith("\r") ? "\r" : ""));
    } else {
      for (int q = k; q <= e2; q++) out.add(raw[q]);
    }
    if (e2 == lastEnd && e2 + 1 < raw.length) {
      out.add(mark + (raw[e2].endsWith("\r") ? "\r" : cr));
      placed = true;
    }
    k = e2 + 1;
  }
  StringBuilder sb = new StringBuilder(text.length() + 256);
  for (int i = 0; i < out.size(); i++) {
    if (i > 0) sb.append('\n');
    sb.append((String) out.get(i));
  }
  String body = sb.toString();
  if (!placed) {
    String nl = cr + "\n";
    String pre = (body.length() == 0 || body.endsWith("\n")) ? "" : nl;
    String last = body.endsWith("\n") ? body.substring(0, body.length() - 1) : body;
    if (last.endsWith("\r")) last = last.substring(0, last.length() - 1);
    int bs = 0;
    for (int i = last.length() - 1; i >= 0 && last.charAt(i) == '\\'; i--) bs++;
    if (bs % 2 == 1) pre = pre + nl;
    body = body + pre + (add ? key + "=" + newV + nl : "") + mark + nl;
  }
  String[] rows = mig ? new String[] { key, oldV, newV } : new String[0];
  return new Object[] { body, rows, Boolean.valueOf(mig), kept, Boolean.valueOf(add) };
}""")
# 0.3.4's own plan = migPlanT with 0.3.4's table (the same result, byte for byte)
M(cfg, r"""
public static Object[] migPlan(String text) {
  return migPlanT(text, MIG_ID, MIG_MARK, MIG_KEY, MIG_OLD, MIG_NEW, true, " kept (an admin's value) - the 0.3.4 default is true (rebirth on)");
}""")
