M(cfg, r"""
public static synchronized String migOn(java.nio.file.Path f) {
  MIG_LAST = "";
  if (f == null) return "";
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = migPlan(new String(old, "ISO-8859-1"));
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    boolean mig = ((Boolean) r[2]).booleanValue();
    boolean add = ((Boolean) r[4]).booleanValue();
    if (!migSame(old, data, mig, add)) {
      warn("config.properties NOT updated for 0.3.4 (rebirth on): the update would change another setting (the file is used as it is; the next start tries again)");
      return "";
    }
    int fi = migFileIdx();
    if (fi < 0) return "";
    @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), MIG_WHO, "before the 0.3.4 rebirth on update (false -> true)");
    if (!migSaved(fi, old)) {
      warn("config.properties NOT updated for 0.3.4 (rebirth on): the old file could not be kept in config-history (the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    String[] rows = (String[]) r[1];
    for (int i = 0; i + 2 < rows.length; i += 3) @PKG@.CfgLog.enqueue(migLine(rows[i], rows[i + 1], rows[i + 2]));
    if (rows.length > 0) @PKG@.CfgLog.flush();
    String msg = "config.properties updated for 0.3.4: " + (mig ? MIG_KEY + " false -> true" + (add ? " (line added - the file had none and read false)" : "") + " (rebirth is ON for every player, Skyy 2026-10-16; Server Setup -> Changes -> Undo = false)" : "no setting changed - 0.3.4 marker added") + " - the old file is in config-history";
    info(msg);
    String kept = (String) r[3];
    if (kept.length() > 0) { info(kept); msg = msg + "\n" + kept; }
    MIG_LAST = msg;
    return msg;
  } catch (Throwable t) {
    warn("could not update config.properties for 0.3.4 (rebirth on; the file is used as it is): " + t);
    return "";
  }
}""")
