M(tree, r"""
public static String gate(String k) {
  if (!@PKG@.RbStore.validKey(k) || @PKG@.RbStore.DIR == null) return "-This profile cannot use the rebirth tree (no data folder).";
  if (@PKG@.RbStore.BUSY.containsKey(k) || (@PKG@.RbJournal.DIR != null && @PKG@.RbJournal.open(k))) return "-A rebirth is running on this profile - try again after it.";
  return null;
}""")
M(tree, r"""
public static String buy(String k, java.util.UUID u, int idx, int expect, boolean allowed) {
  if (!allowed) return "-Rebirth is switched off on this server.";
  if (idx < 0 || idx >= NID.length) return "-Pick a node first.";
  String g = gate(k);
  if (g != null) return g;
  java.util.Properties cur = @PKG@.RbStore.readNow(k);
  if (cur == null) return "-Your rebirth file cannot be read - nothing changed (server log).";
  int a = NARM[idx];
  String arm = @PKG@.RbMath.ARMS[a];
  int l = lv(cur, idx);
  if (l != expect) return "-" + NNAME[idx] + " changed meanwhile (now level " + l + ") - look again.";
  if (l >= NMAX[idx]) return "-" + NNAME[idx] + " is already at its max level.";
  int r = NROW[idx];
  if (r >= openRows(cur, a)) return "-Row " + (r + 1) + " of the " + arm + " arm is still locked.";
  long c = cost(armLevels(cur, a));
  long have = big(cur, "pts." + arm);
  if (have < c) return "-Not enough " + arm + " points: this level costs " + c + ", you have " + have + ".";
  java.util.Properties p = new java.util.Properties();
  p.putAll(cur);
  p.setProperty("pts." + arm, String.valueOf(have - c));
  p.setProperty("spent." + arm, String.valueOf(big(cur, "spent." + arm) + c));
  p.setProperty("node." + NID[idx], String.valueOf(l + 1));
  if (NTITLE[idx].length() > 0) p.setProperty("title", NTITLE[idx]);
  String e = @PKG@.RbStore.save(k, p);
  if (e != null) return "-Could not save - nothing changed: " + e;
  BUYS.incrementAndGet();
  @PKG@.RbCfg.info("tree: " + k + " bought " + NID[idx] + " level " + (l + 1) + " for " + c + " " + arm + " points (" + (have - c) + " left)");
  if (u != null) { try { @PKG@.RbPub.publish(u); } catch (Throwable t) { } }
  return "+" + NNAME[idx] + " level " + (l + 1) + " bought - " + c + " " + arm + (c == 1L ? " point" : " points") + " spent.";
}""")
# admin: every level of arm a (-1 = all arms) back to 0 and exactly spent.<Arm> back to pts.<Arm>; a keystone title of a refunded arm
# reverts to Void-Touched <n> (none at 0 rebirths)
M(tree, r"""
public static String refund(String k, java.util.UUID u, int a) {
  if (a < -1 || a > 7) return "-Usage: /rebirthadmin refund <arm|all>";
  String g = gate(k);
  if (g != null) return g;
  java.util.Properties cur = @PKG@.RbStore.readNow(k);
  if (cur == null) return "-The rebirth file cannot be read - nothing changed.";
  java.util.Properties p = new java.util.Properties();
  p.putAll(cur);
  long back = 0L;
  int lvls = 0;
  String t = title(cur);
  boolean keyTitle = false;
  for (int i = 0; i < 8; i++) {
    if (a >= 0 && i != a) continue;
    String arm = @PKG@.RbMath.ARMS[i];
    long sp = big(cur, "spent." + arm);
    lvls += armLevels(cur, i);
    for (int k2 = i * 11; k2 < i * 11 + 11; k2++) {
      p.remove("node." + NID[k2]);
      if (NTITLE[k2].length() > 0 && NTITLE[k2].equals(t)) keyTitle = true;
    }
    p.remove("spent." + arm);
    if (sp > 0L) p.setProperty("pts." + arm, String.valueOf(big(cur, "pts." + arm) + sp));
    back += sp;
  }
  if (keyTitle) {
    int n = @PKG@.RbStore.num(cur, "n");
    if (n > 0) p.setProperty("title", "Void-Touched " + @PKG@.RbMath.roman(n)); else p.remove("title");
  }
  String e = @PKG@.RbStore.save(k, p);
  if (e != null) return "-Could not save - nothing changed: " + e;
  @PKG@.RbCfg.info("tree: admin refund of " + (a < 0 ? "every arm" : @PKG@.RbMath.ARMS[a]) + " on " + k + ": " + lvls + " levels, " + back + " points back");
  if (u != null) { try { @PKG@.RbPub.publish(u); } catch (Throwable x) { } }
  return "+Refunded " + (a < 0 ? "every arm" : "the " + @PKG@.RbMath.ARMS[a] + " arm") + ": " + lvls + " levels reset, " + back + " points back.";
}""")
