# the page lines of one answer (the contract's PAGE TEXT), at most 12 in out; returns the count of kind 0 / 1 / 2 lines
M(chk, r"""
public static int[] detail(String s, String who, java.util.ArrayList out) {
  int[] c = new int[3];
  if (s == null) return c;
  String[] ls = s.split("\n");
  for (int i = 1; i < ls.length; i++) {
    String[] f = ls[i].split("\t");
    if (f.length < 6) continue;
    int kind = -1;
    try { kind = Integer.parseInt(f[1].trim()); } catch (Throwable t) { kind = -1; }
    if (kind < 0 || kind > 2) continue;
    c[kind] = c[kind] + 1;
    if (out.size() >= 12) continue;
    String nm = f[5].trim();
    if (nm.length() > 40) nm = nm.substring(0, 40);
    String q = f[2].trim();
    if (kind == 1) out.add(nm + " x" + q + " - " + (who.equals("AH") ? "will be cancelled, the item waits in /ah > Manage" : "Bazaar order, will be cancelled"));
    else if (kind == 0) out.add(nm + " x" + q + " - " + (who.equals("AH") ? "can't be pulled yet" : "Bazaar order, can't be closed yet"));
    else out.add(nm + " x" + q + " SOLD - claim your " + f[3].trim() + " coins in /ah > Manage first");
  }
  return c;
}""")
# Object[]{ Integer 0 ok / 1 only closable orders (Continue) / 2 blocked, String the requirement line, String its colour, ArrayList the
# hover lines, Long closable }. Unclaimed AH sale coins block (default - the player claims them first; Continue is not offered).
M(chk, r"""
public static Object[] market(String k) {
  java.util.ArrayList d = new java.util.ArrayList();
  String bz = ask("bazaar:fn:wouldclose", k);
  String ah = ask("ah:fn:wouldclose", k);
  if (bz == null) return new Object[] { Integer.valueOf(2), "NO  Needs SkyyBazaar 0.1.11+", "@BAD@", d, Long.valueOf(0L) };
  if (ah == null) return new Object[] { Integer.valueOf(2), "NO  Needs SkyyAuctions 0.1.5", "@BAD@", d, Long.valueOf(0L) };
  long[] hb = head(bz);
  long[] ha = head(ah);
  if (hb == null || ha == null) {
    d.add("The Bazaar answered " + line1(bz) + ", the AH " + line1(ah));
    return new Object[] { Integer.valueOf(2), "NO  Bazaar / AH not answering", "@BAD@", d, Long.valueOf(0L) };
  }
  int[] cb = detail(bz, "Bazaar", d);
  int[] ca = detail(ah, "AH", d);
  long close = hb[0] + ha[0];
  long block = hb[1] + ha[1];
  long coins = (long) (ca[2] + cb[2]);
  if (ha[2] > coins) d.add("Items waiting in /ah > Manage are kept through a rebirth - no need to claim them first.");
  if (coins > 0L) return new Object[] { Integer.valueOf(2), "NO  Claim AH sale coins first", "@BAD@", d, Long.valueOf(close) };
  if (block > 0L) return new Object[] { Integer.valueOf(2), "NO  " + block + " can't be closed yet", "@BAD@", d, Long.valueOf(close) };
  if (close > 0L) return new Object[] { Integer.valueOf(1), "NO  " + close + " to close - Continue", "@WARN@", d, Long.valueOf(close) };
  return new Object[] { Integer.valueOf(0), "OK  No Bazaar / AH orders", "@GOOD@", d, Long.valueOf(0L) };
}""".replace("@GOOD@", GOOD).replace("@BAD@", BAD).replace("@WARN@", WARN))
