# 0.3 R4 CONTINUE (RbRun mode 5 on SkyyRebirth-IO): no rebirth in flight (the journal), bazaar:fn:closeall + ah:fn:closeall OUTSIDE the
# transaction (spec 2.4), then startNow = step 0 (busy claimed + published, the market re-check, BEGIN) and the rest. "+..." / "-why"
M(tx, r"""
public static String continueNow(String k, java.util.UUID u) {
  if (@PKG@.RbStore.BUSY.containsKey(k) || @PKG@.RbJournal.open(k)) return "-A rebirth is already running on this profile.";
  String bz = @PKG@.RbCheck.closeAll("bazaar:fn:closeall", k);
  int nb = @PKG@.RbCheck.closed(bz);
  String ah = nb < 0 ? "skipped (the Bazaar did not close)" : @PKG@.RbCheck.closeAll("ah:fn:closeall", k);   // the AH only after the Bazaar closed
  int na = nb < 0 ? -1 : @PKG@.RbCheck.closed(ah);
  note(k, "continue on " + k + ": bazaar:fn:closeall " + bz + ", ah:fn:closeall " + ah);
  if (nb < 0 || na < 0) return "-" + @PKG@.RbCheck.closeWhy(bz, ah);
  if (nb + na > 0) tell(u == null ? null : u.toString(), "[Rebirth] Closed " + (nb + na) + " Bazaar / AH order(s) - the items wait in /ah > Manage (listing fees are kept).", "#ffcc00");
  return startNow(k, u);
}""")
# the player's click (rebirth ON, every requirement met on the page's checks - or, cont, every one but closable orders) -> "+..." started
