M(tx, r"""
public static String playerStart(java.util.UUID u, String world, boolean cont) {
  if (!@PKG@.RbCfg.ON) return "-Rebirth is switched off on this server.";
  String k = @PKG@.RbCfg.pkey(u);
  int n = @PKG@.RbStore.n(k);
  Object[] req = @PKG@.RbCheck.reqs(u, world, n);
  if (cont) { if (!Boolean.TRUE.equals(req[3])) return "-Continue is not offered now - open /rebirth again."; }
  else if (!Boolean.TRUE.equals(req[2])) return "-Not ready yet - the NO lines on /rebirth say what is missing.";
  String ok = cont ? "+Closing your Bazaar / AH orders, then the void imprints your soul ... (rebirth " + (n + 1) + ")" : "+The void is imprinting your soul ... (rebirth " + (n + 1) + ")";
  java.util.concurrent.ExecutorService e = @PKG@.RbStore.IO;   // fix round: begin's file steps (read, journal + fsync) off the world thread
  if (e != null) {
    try { e.execute(new @PKG@.RbRun(k, cont ? 5 : 4, u)); return ok; } catch (Throwable t) { }
  }
  String r = cont ? continueNow(k, u) : startNow(k, u);
  return r.startsWith("+") ? ok : r;
}""")
