M(pl, r"""
public void setup() {
  @PKG@.RbCfg.LOG = getLogger();
  java.nio.file.Path dir = getDataDirectory().resolveSibling("Skyy_SkyyRebirth");
  @PKG@.RbCfg.DIR = dir;
  @PKG@.RbCfg.FILE = dir.resolve("config.properties");
  // 0.3.4: the one-time rebirth.on false -> true update of an existing config.properties, BEFORE loadCfg / CfgPub.start (the kit's history +
  // change log folder and logger first; CfgPub.start sets the same again)
  try {
    @PKG@.CfgRows.LOG = getLogger();
    @PKG@.CfgRows.HOME = dir;
    @PKG@.CfgHist.init();
    @PKG@.CfgLog.init();
    @PKG@.RbCfg.migOn(@PKG@.RbCfg.FILE);
  } catch (Throwable t) { @PKG@.RbCfg.warn("the 0.3.4 rebirth on update was skipped: " + t); }
  try { @PKG@.RbCfg.migMax(@PKG@.RbCfg.FILE); } catch (Throwable t) { @PKG@.RbCfg.warn("the 0.3.6 no rebirth limit update was skipped: " + t); }   // 0.3.6
  String c = @PKG@.RbCfg.loadCfg(true);
  @PKG@.RbStore.DIR = dir.resolve("players");
  @PKG@.RbJournal.DIR = dir.resolve("journal");   // 0.2: the two-phase commit journals
  int open = @PKG@.RbTx.startup();
  @PKG@.RbStore.start();
  java.util.Map b = @PKG@.RbCfg.bridge();
  b.put("rebirth:fn:count", new @PKG@.RbFn(0));
  b.put("rebirth:fn:cap", new @PKG@.RbFn(1));
  b.put("rebirth:fn:node", new @PKG@.RbFn(2));
  b.put("rebirth:fn:dustmult", new @PKG@.RbFn(3));
  b.put("rebirth:fn:busy", new @PKG@.RbFn(4));
  b.put("rebirth:fn:decision", new @PKG@.RbFn(5));
  b.put("rebirth:fn:stat", new @PKG@.RbFn(6));    // 0.3 the tree
  b.put("rebirth:fn:title", new @PKG@.RbFn(7));
  b.put("rebirth:fn:cos", new @PKG@.RbFn(8));
  b.put("rebirth:version", "@VERSION@");
  @PKG@.CfgPub.start(getDataDirectory().getParent(), getLogger());
  getCommandRegistry().registerCommand(new @PKG@.RbCmd());
  getCommandRegistry().registerCommand(new @PKG@.RbAdminCmd());
  this.ticker = @HSV@.SCHEDULED_EXECUTOR.scheduleAtFixedRate(new @PKG@.RbTick(), 5L, 1L, java.util.concurrent.TimeUnit.SECONDS);   // fix round: 1 s
  this.recov = @HSV@.SCHEDULED_EXECUTOR.scheduleAtFixedRate(new @PKG@.RbRun(null, 3), 10L, 30L, java.util.concurrent.TimeUnit.SECONDS);
  getLogger().at(java.util.logging.Level.INFO).log("[SkyyRebirth] @VERSION@ ready (@KITID@) - rebirth is " + (@PKG@.RbCfg.ON ? "ON: /rebirth for every player" : "OFF: /rebirth for admins only (view + /rebirthadmin tests; Server Setup - Rebirth switches it on)") + "; two-phase commit with " + (@PKG@.RbJournal.missing() == null ? "every part loaded so far" : "parts still loading (" + @PKG@.RbJournal.missing() + ")") + " (skills, coins, bank, gear; Continue closes Bazaar / AH orders through " + (@PKG@.RbCfg.bridge().get("ah:fn:closeall") != null && @PKG@.RbCfg.bridge().get("bazaar:fn:closeall") != null ? "SkyyBazaar + SkyyAuctions" : "SkyyBazaar 0.1.11+ / SkyyAuctions 0.1.5+ (still loading or missing)") + "), the rebirth tree (" + @PKG@.RbTree.NID.length + " nodes; the Farming arm counts Farming + Ranching + Orchard; rebirth:fn:node / stat / title / cos, skill:bonus source rebirth), " + open + " open rebirth journal(s) at start (recovered 10 s after start, then every 30 s); bridge rebirth:n:<uuid> + rebirth:busy:<uuid> + rebirth:fn:count / cap / node / dustmult / busy / decision (caps +" + @PKG@.RbCfg.LEVELS + " levels per rebirth, Exploration never; SkyySkills 0.4.35+ reads them); " + c + "; data in " + dir);
}""".replace("@KITID@", KIT_ID))
M(pl, r"""
protected void shutdown() {
  try { if (this.ticker != null) this.ticker.cancel(false); } catch (Throwable t) { }
  try { if (this.recov != null) this.recov.cancel(false); } catch (Throwable t) { }
  try { @PKG@.RbStore.stop(); } catch (Throwable t) { }
  try { @PKG@.CfgPub.shutdown(); } catch (Throwable t) { }
  try { @PKG@.RbPub.clearAll(); } catch (Throwable t) { }
  java.util.Map b = @PKG@.RbCfg.bridge();
  try { b.remove("rebirth:fn:count"); b.remove("rebirth:fn:cap"); b.remove("rebirth:fn:node"); b.remove("rebirth:fn:dustmult"); b.remove("rebirth:fn:busy"); b.remove("rebirth:fn:decision"); b.remove("rebirth:fn:stat"); b.remove("rebirth:fn:title"); b.remove("rebirth:fn:cos"); b.remove("rebirth:version"); } catch (Throwable t) { }
  super.shutdown();
}""")

